        throw new KitError({
            ...BorrowError.UNRECOGNIZED_RESPONSE_CHAIN,
            recoverability: 'FATAL',
            message: `Unrecognized Borrow Service response chain: ${chain}`,
            cause: {
                trace: {
                    chain
                }
            }
        });
