// onBehalf, address receiver)`. MarketParams is a five-word static tuple encoded
// inline and led by `loanToken`, so the arguments after it start at word 5.
const BORROW_LEG_LOAN_TOKEN_WORD = 0;
const BORROW_LEG_ASSETS_WORD = 5;
