    // of walletAddress/chain/marketId, and rejects an incomplete open tuple.
    // Omitting `chain` on borrow-more is safe — the loan supplies it, and the
    // caller checks the response chain against the one it signed for.
    //
    // Spread only defined optional fields so exactOptionalPropertyTypes does not
    // emit `undefined` values on the wire.
    const body = {
        amount: params.loanAssetAmount,
        ...params.loanId === undefined ? {
            walletAddress: params.walletAddress,
            chain: requireBorrowApiChain(params.chain),
            marketId: params.marketId
        } : {
            loanId: params.loanId
        },
        ...params.slippageBps !== undefined && {
            slippageBps: params.slippageBps
        }
    };
    const response = await postBorrowService({
        providerConfig,
        requestConfig: params.config,
        path: '/loans/borrow',
        body,
        responseGuard: isBorrowExecution,
        operation: 'borrow',
        idempotent: true,
        credential: 'optional',
        ...params.idempotencyKey !== undefined && {
            idempotencyKey: params.idempotencyKey
        }
    });
