    const url = new URL(`${KITS_API_PREFIX}/claimRewards/quote`, baseUrl);
    const requestBody = {
        address: params.address,
        chain: params.chain
    };
    try {
        const response = await pollApiPost(url.toString(), requestBody, isClaimRewardsQuoteResponse, pollingConfig);
        return {
            rewards: response.data.rewards.map(toClaimedAmount)
        };
    } catch (error) {
        throw parseBorrowApiError(error, {
            operation: 'getRewards'
        });
    }
